// ═══════════════════════════════════════════════════════════════════════════
// v180 — receipts that can be checked
// ═══════════════════════════════════════════════════════════════════════════
// Every receipt carries a QR code / link to verify.html. The link holds the
// building, the receipt number, the amount printed and a random check code
// stored on the payment (verifyCode; payments of one receipt share it). The
// public rpc verify_receipt (supabase/phase2p-v180.sql) answers valid,
// changed, cancelled or not found, without names or phone numbers. Only the
// manager's phone hands out codes; a deleted payment's receipt is kept in
// state.voidedReceipts so the check can say it was cancelled.
const VERIFY_ALPHABET = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789";
const APP_HOME = "https://building-account-tracker.vercel.app";

function newVerifyCode() {
  const bytes = new Uint8Array(10);
  crypto.getRandomValues(bytes);
  return [...bytes].map((b) => VERIFY_ALPHABET[b % 32]).join("");
}

function canIssueReceiptChecks() {
  return sessionMode === "owner" && !isViewerSession() && canPushDocument();
}

// Gives every receipted payment a check code; returns how many changed.
function addReceiptVerifyCodes(target = state) {
  const payments = (target.transactions || []).filter((t) => isReceiptablePayment(t) && t.receiptRef);
  const byRef = new Map();
  payments.forEach((t) => { if (t.verifyCode && !byRef.has(t.receiptRef)) byRef.set(t.receiptRef, t.verifyCode); });
  let added = 0;
  payments.forEach((t) => {
    if (t.verifyCode) return;
    if (!byRef.has(t.receiptRef)) byRef.set(t.receiptRef, newVerifyCode());
    t.verifyCode = byRef.get(t.receiptRef);
    added += 1;
  });
  return added;
}

// Receipts whose payments are gone between two copies of the building.
function voidedReceiptsBetween(previous, next) {
  const kept = new Set((next.transactions || []).filter((t) => t.verifyCode).map((t) => `${t.receiptRef}:${t.verifyCode}`));
  const gone = new Map();
  (previous.transactions || []).filter((t) => isReceiptablePayment(t) && t.receiptRef && t.verifyCode).forEach((t) => {
    const id = `${t.receiptRef}:${t.verifyCode}`;
    if (kept.has(id)) return;
    const entry = gone.get(id) || { id, ref: t.receiptRef, code: t.verifyCode, unit: (previous.tenants || []).find((x) => x.id === t.tenantId)?.unit || "", amountUsd: 0, at: new Date().toISOString() };
    entry.amountUsd = roundUsd(entry.amountUsd + transactionNetUsd(t));
    gone.set(id, entry);
  });
  return [...gone.values()];
}

function recordVoidedReceipts(previous) {
  const gone = voidedReceiptsBetween(previous, state);
  if (!gone.length) return;
  const known = new Set((state.voidedReceipts || []).map((v) => v.id));
  state.voidedReceipts = [...(state.voidedReceipts || []), ...gone.filter((v) => !known.has(v.id))].slice(-2000);
}

function receiptCheckLink({ ref, code, amount, kind = "building", lang = state.settings?.language || "en" }) {
  if (!ref || !code) return "";
  const origin = typeof location !== "undefined" && /^https?:/.test(location.origin || "") ? location.origin : APP_HOME;
  const q = new URLSearchParams({ b: currentBuildingId(), r: ref, c: code, a: String(Math.round(Number(amount || 0) * 100) / 100), l: lang === "ar" ? "ar" : "en" });
  if (kind === "rent") q.set("k", "rent");
  return `${origin}/verify?${q}`;
}

// After a sync on the manager's phone: give older receipts their codes.
function backfillReceiptChecks() {
  if (!canIssueReceiptChecks()) return;
  if (state.transactions.some((t) => isReceiptablePayment(t) && t.receiptRef && !t.verifyCode)) saveState();
}

// A QR code drawn into a PDF page (an image, like the Arabic text images).
function pdfQrCommand(text, x, y, size) {
  const canvas = qrCanvas(text, 480);
  const binary = atob(canvas.toDataURL("image/jpeg", 0.95).split(",")[1] || "");
  let hex = "";
  for (let i = 0; i < binary.length; i += 1) hex += binary.charCodeAt(i).toString(16).padStart(2, "0");
  const img = { name: `Tx${pdfTextImages.length + 1}`, width: canvas.width, height: canvas.height, ascent: canvas.height, hex };
  pdfTextImages.push(img);
  return `q ${size} 0 0 ${size} ${x} ${y} cm /${img.name} Do Q`;
}

// Rent payments recorded before v180 get their check codes once.
let rentCodesBackfilled = false;
async function backfillRentVerifyCodes() {
  if (rentCodesBackfilled || !isOwnerSession() || isViewerSession()) return;
  rentCodesBackfilled = true;
  for (const lease of rentalLeases || []) {
    if (!(lease.payments || []).some((p) => !p.verifyCode)) continue;
    await saveLease({ ...lease, payments: lease.payments.map((p) => (p.verifyCode ? p : { ...p, verifyCode: newVerifyCode() })) });
  }
}

// ═══════════════════════════════════════════════════════════════════════════
// v182 — receipts show what a payment paid for
// ═══════════════════════════════════════════════════════════════════════════
// A monthly payment's receipt lists, for each month, the monthly fee (or the
// share of expenses), the generator and the water, what was due and what this
// payment covered. Within a month a payment covers the fee first, then the
// generator, then the water, after whatever was already paid for that month.
const RECEIPT_COLUMNS = ["Month", "Item", "Due", "This payment", "Status"];

function receiptMonthParts(tenantId, month) {
  const fixed = isFixedMode();
  return [
    [fixed ? "Monthly fee" : "Share of expenses", fixed ? getExpectedForTenant(tenantId, month) : getTenantExpenseShare(tenantId, month)],
    ["Generator", getTenantServicesDue(tenantId, { serviceType: "generator", month })],
    ["Water", getTenantServicesDue(tenantId, { serviceType: "water", month })],
  ].map(([label, due]) => [label, roundUsd(due)]).filter(([, due]) => due > 0.005);
}

// Paid for the month before this payment (other receipts, earlier first).
function paidForMonthBefore(entry, receiptEntries) {
  const mine = new Set(receiptEntries.map((e) => e.id));
  const key = (t) => `${t.date || ""}|${t.id}`;
  return roundUsd(state.transactions
    .filter((t) => isMonthlyPayment(t) && t.tenantId === entry.tenantId && t.forMonth === entry.forMonth && !mine.has(t.id) && key(t) < key(entry))
    .reduce((sum, t) => sum + transactionNetUsd(t), 0));
}

// One row per part of the month's due (plus a total row when there are
// several), as [month, item, due, this payment, status]; total rows carry
// .total = true.
function receiptBreakdownRows(data) {
  const rows = [];
  data.receiptEntries.forEach((entry) => {
    const month = formatMonth(entry.forMonth);
    const applied = roundUsd(transactionNetUsd(entry));
    const parts = receiptMonthParts(data.tenant.id, entry.forMonth);
    if (!parts.length) {
      rows.push([month, "Monthly dues", "-", formatUsd(applied), paymentStatus(data.tenant.id, entry.forMonth).label]);
      return;
    }
    let before = paidForMonthBefore(entry, data.receiptEntries);
    // The month as of this payment: paid in full, or partly.
    const totalDue = roundUsd(parts.reduce((s, [, due]) => s + due, 0));
    const status = before + applied >= totalDue - 0.005 ? "Paid" : before + applied > 0.005 ? "Partial" : "Due";
    let left = applied;
    parts.forEach(([label, due], index) => {
      const covered = Math.min(due, Math.max(0, before));
      before -= covered;
      const take = roundUsd(Math.max(0, Math.min(due - covered, left)));
      left = roundUsd(left - take);
      rows.push([index === 0 ? month : "", label, formatUsd(due), formatUsd(take), parts.length === 1 ? status : ""]);
    });
    if (left > 0.005) rows.push(["", "Extra (credit)", "", formatUsd(left), ""]);
    if (parts.length > 1) {
      const total = Object.assign(["", "Total for the month", formatUsd(totalDue), formatUsd(applied), status], { total: true });
      rows.push(total);
    }
  });
  return rows;
}

// Guard against one bad cloud write cascading into data loss on every device.
// The auto-sync path adopts the cloud copy whenever this device has nothing
// unsynced — which is correct, EXCEPT when the cloud copy has lost everything.
// Then adopting it silently deletes real data (and the now-empty device pushes
// that emptiness back, so the loss spreads). Refuse it and let the building manager decide.
function remoteWouldWipeLocalData(remote) {
  const size = (s) => (s?.tenants?.length || 0) + (s?.transactions?.length || 0);
  return size(state) > 0 && size(remote) === 0;
}

async function syncFromSheet({ silent = false } = {}) {
  if (!hasCloudConfig()) return;
  if (document.querySelector("dialog[open]")) return;
  if (cloudSaveInFlight) return;
  // A phone with no identity that is not in owner mode (fresh phone, login
  // screen, PIN tenant): fetch nothing, so an unlinked phone never downloads
  // the building.
  if (usesOwnerAccounts() && !authSession && sessionMode !== "owner") return;
  if (isTenantSession() || isConciergeSession()) {
    // A tenant (or concierge) phone never has local edits: take the server's copy.
    try {
      const remote = await cloudLoadState();
      if (!remote) return;
      state = hydrateState(remote);
      localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
      if (sessionMode === "tenant" || sessionMode === "concierge") renderAll();
      setSyncChip("saved");
    } catch (error) {
      reportSyncProblem(error);
    }
    return;
  }
  if (!silent) renderCloudStatus(`Syncing from the ${cloudProviderLabel()}…`);
  try {
    const remote = await cloudLoadState();
    if (!remote) return;
    const sync = loadSyncMeta();
    const remoteToken = remote.meta?.token || "";
    const dirty = localHasUnsyncedChanges();

    if (remoteToken && remoteToken === sync.lastSyncedToken) {
      // Cloud unchanged since this device last synced. When clean, this is the
      // round trip that earns "Saved" (boot shows "Saving…" until one happens).
      if (dirty) queueCloudSave();
      else { setSyncChip("saved"); backfillReceiptChecks(); }
      return;
    }
    if (dirty) {
      // Foreign changes AND unsynced local changes: merge, then push the result.
      state = hydrateState(mergeStates(state, remote));
      localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
      populateTenantSelect();
      renderAll();
      queueCloudSave();
    } else if (remoteWouldWipeLocalData(remote)) {
      // Cloud lost everything; this device still has data. Keep local, say so
      // loudly, and push nothing automatically either way.
      renderCloudStatus(
        tr("The cloud copy is empty but this device has data. Nothing was replaced. Tap the sync chip to upload this device's data."),
      );
      reportSyncProblem(Object.assign(new Error("The cloud copy is empty but this device has data. Nothing was replaced. Tap the sync chip to upload this device's data."), { code: "empty-cloud" }));
      if (!silent) showToast("Cloud copy is empty — kept this device's data");
      return;
    } else {
      // No local changes: safe to adopt the cloud state.
      state = hydrateState(remote);
      localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
      saveSyncMeta({ lastSyncedToken: remoteToken, lastPushedRev: Number(state.meta?.rev || 0) });
      populateTenantSelect();
      renderAll();
    }
    renderCloudStatus(`Last synced at ${new Date().toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" })}`);
    setSyncChip("saved");
    refreshBalanceSnapshot();
    backfillReceiptChecks();
  } catch (error) {
    reportSyncProblem(error);
    if (!silent) renderCloudStatus(lastSyncProblem);
  }
}

async function boot() {
  // Apply the last-used language immediately so the login screen renders correctly.
  applyLanguage(localStorage.getItem(LANG_KEY) || "en");
  const response = await fetch("data/seed.json", { cache: "no-store" });
  seedState = hydrateState(await response.json());
  const stored = localStorage.getItem(STORAGE_KEY);
  state = stored ? hydrateState(JSON.parse(stored)) : hydrateState(seedState);
  if (ensureAllReceiptReferences()) saveState({ sync: false });
  applyLanguage(state.settings.language);

  attachEvents();
  populateTenantSelect();
  renderAll();
  // Do NOT claim "Saved" here: nothing has been synced yet at boot. Showing
  // in-progress means the chip can only say "Saved" after a real round trip.
  setSyncChip(hasCloudConfig() ? "saving" : "local");
  showLoginScreen();
  if (isConciergeSession()) enterAsConcierge();
  showAppLock();

  if ("serviceWorker" in navigator) navigator.serviceWorker.register("sw.js").catch(() => {});

  // Returning from Google? Finish signing in before the first sync, so that
  // sync already runs as the building manager.
  captureAdminInvite();
  captureLaunchParams();
  runLaunchAction();
  if (usesOwnerAccounts()) await completeGoogleSignIn();
  if (await checkBuildingChoice()) return;

  setFirstSyncLoading(true);
  await syncFromSheet();
  setFirstSyncLoading(false);
  void refreshTechRequests();

  setInterval(() => { if (sessionMode) syncFromSheet({ silent: true }); }, 60000);
}

boot().catch((error) => {
  document.body.innerHTML = `<main class="app-shell"><section class="panel"><h1>BUILDING ACCOUNT TRACKER ${APP_VERSION}</h1><p>${error.message}</p></section></main>`;
});

